				for (int k = 1; k <= N; k++) {
					int c = HCF(i, j);
					int d = HCF(c, k);
					sum = sum + d;
				}
			}
		}
		System.out.println(sum);

	}

	public static int HCF(int a, int b) {
		int temp = -1;
		int x = Math.max(a, b);
		int y = Math.min(a, b);
		while (x > 0) {
			temp = x;
			x = y % x;
			y = temp;
		}
		return y;
	}

}

