    System.out.println(sum);
  }

  public static int gcd(int[] list) {
    if (list[1]%list[0] == 0 && list[2]%list[0] == 0) {
      return list[0];
    } else {
      for (int i = list[0]/2; i > 0; i--) {
        if (list[0]%i != 0) continue;
        if (list[1]%i == 0 && list[2]%i == 0) {
          return i;
        }
      }
      return 1;
    }
  }
}

