		FastScanner sc = new FastScanner(System.in);
		long n = sc.nextLong(), k = sc.nextLong(), q = sc.nextLong();
		long[] a = new long[(int)n];
		Arrays.fill(a, 0);
		for(int i = 0; i < q; i++) {
			a[sc.nextInt()-1] += 1;
		}
		for(int i = 0; i < n; i++) {
