import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyScanner in = new MyScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B solver = new B();
        solver.solve(1, in, out);
        out.close();
    }

    static class B {
        public void solve(int testNumber, MyScanner in, PrintWriter out) {
            int N = in.nextInt();
            int[] A = in.nextIntArray(N);
            int[] B = in.nextIntArray(N);
            int[] C = in.nextIntArray(N - 1);

            long sum = 0;
            int prev = -2;
            for (int i = 0; i < N; i++) {
                int n = A[i] - 1;
                sum += B[n];
                if (prev + 1 == n) {
                    sum += C[prev];
                }
                prev = n;
            }
            out.println(sum);
        }

    }

    static class MyScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public MyScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String rl = in.readLine();
                    if (rl == null) {
                        return null;
                    }
                    st = new StringTokenizer(rl);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int elements = sc.nextInt();
        int[] order = new int[elements];
        for (int i = 0; i < elements; i++) {
            order[i] = sc.nextInt()-1;
        }
        int[] point = new int[elements];
        for (int i = 0; i < elements; i++) {
            point[i] = sc.nextInt();
        }
        int[] bonus = new int[elements-1];
        for (int i = 0; i < elements-1; i++) {
            bonus[i] = sc.nextInt();
        }

        solve(order,point,bonus);
    }

    public static void solve(int[] order,int[] point,int[] bonus){
        int result = 0;
        int prev = order.length;
        for(int now:order){
            result += point[now];
            if(now-prev==1){
                result += bonus[prev];
            }
            prev = now;
        }
        System.out.println(result);
    }
}

